import { getPluginName } from '../hosts/pluginContext';

export type TelemetryMode = 'full' | 'metrics' | 'off';

export class TelemetryPolicyMismatchError extends Error {
  readonly reason = 'telemetry_policy_mismatch';

  constructor() {
    super(
      'The running Rivet process has a different or unverified telemetry policy. Finish its work, stop that process explicitly, then reopen the plugin with the same telemetry preference.',
    );
    this.name = 'TelemetryPolicyMismatchError';
  }
}

export const getTelemetryMode = (
  env: NodeJS.ProcessEnv = process.env,
): TelemetryMode => {
  if (env.RIVET_TELEMETRY_DISABLED === '1') return 'off';
  return getPluginName(env) ? 'metrics' : 'full';
};

export const assertTelemetryMode = (
  actual: unknown,
  env: NodeJS.ProcessEnv = process.env,
): void => {
  if (getPluginName(env) && actual !== getTelemetryMode(env)) {
    throw new TelemetryPolicyMismatchError();
  }
};
